  isRecord,
  MAX_TERMS_LENGTH,
  type Country,
} from "@quote/contract";

export const TERMS_UID = "api::quote-content.terms";

export function projectTerms(document: unknown, country: Country) {
  if (!isRecord(document)) return null;
  const text = document["body"];
  if (
    document["country"] !== country ||
    typeof text !== "string" ||
    text.length > MAX_TERMS_LENGTH
  ) {
    return null;
  }
  const revision = createHash("sha256")
    .update(JSON.stringify([1, country, text]), "utf8")
    .digest("hex");
  return decodeTerms({ schemaVersion: 1, country, revision, text }, country);
}
import { isRecord, type Country } from "./content.ts";

export const MAX_TERMS_LENGTH = 20_000;

export type Terms = {
  schemaVersion: 1;
  country: Country;
  revision: string;
  text: string;
};

export function decodeTerms(input: unknown, country: Country): Terms | null {
  if (!isRecord(input)) return null;
  const { schemaVersion, revision, text } = input;
  if (
    schemaVersion !== 1 ||
    input["country"] !== country ||
    typeof revision !== "string" ||
    !/^[0-9a-f]{64}$/.test(revision) ||
    typeof text !== "string" ||
    text.length > MAX_TERMS_LENGTH ||
    !text.trim()
  )
    return null;
  return { schemaVersion, country, revision, text };
}
