    14	async function restrictPublicRole(strapi: Core.Strapi) {
    15	  await strapi.db.transaction(async () => {
    16	    const roles = strapi.db.query("plugin::users-permissions.role");
    17	    const publicRole = await roles.findOne({ where: { type: "public" } });
