    19	      throw new Error(
    20	        "The Public role is unavailable during quote initialization.",
    21	      );
    22	
    23	    const permissions = strapi.db.query("plugin::users-permissions.permission");
    24	    const grants = await permissions.findMany({
    25	      select: ["id", "action"],
    26	      where: { role: publicRole.id },
    27	    });
    28	    const expectedActions = [
    29	      READ_FORM_ACTION,
    30	      READ_PLANS_ACTION,
    31	      READ_TERMS_ACTION,
    32	    ];
    33	    const retained = expectedActions.map((action) =>
    34	      grants.find((grant) => grant.action === action),
    35	    );
    36	    const obsolete = grants
    37	      .filter((grant) => !retained.includes(grant))
    38	      .map(({ id }) => id);
    39	    if (obsolete.length) {
    40	      await permissions.deleteMany({ where: { id: { $in: obsolete } } });
    41	    }
    42	    for (const [index, action] of expectedActions.entries()) {
    43	      if (!retained[index])
    44	        await permissions.create({ data: { action, role: publicRole.id } });
    45	    }
    46	  });
    47	}
