    77	export class QuoteState {
    78	  private readonly http = inject(HttpClient);
    79	  private readonly clock = inject(QUOTE_CLOCK);
    80	  private readonly current = signal<LoadState>({ phase: 'idle' });
    81	  private readonly drafts = signal<Partial<Record<Country, QuoteDraft>>>({});
    82	  private readonly draftRevisions = signal<Partial<Record<Country, number>>>({});
    83	  private request?: Subscription;
    84	  private generation = 0;
    85	
    86	  readonly state = this.current.asReadonly();
    87	
    88	  leave() {
    89	    this.generation++;
    90	    this.request?.unsubscribe();
    91	    this.current.set({ phase: 'idle' });
    92	  }
    93	
    94	  load(country: Country, refresh = false) {
    95	    const state = this.current();
    96	    if (!refresh && state.phase !== 'idle' && state.country === country) return;
    97	    const generation = ++this.generation;
    98	    this.request?.unsubscribe();
    99	    this.current.set({ phase: 'loading', country });
   100	
   101	    const stillCurrent = () =>
   102	      generation === this.generation &&
   103	      this.current().phase === 'loading' &&
   104	      this.currentCountry() === country;
   105	    const unavailable = () => {
   106	      if (stillCurrent()) this.current.set({ phase: 'unavailable', country });
   107	    };
   108	    this.request = this.http
   109	      .get<unknown>(`/api/quote-content/v1/${country}/form`, {
   110	        timeout: 10_000,
   111	      })
   112	      .subscribe({
   113	        next: (input) => {
   114	          if (!stillCurrent()) return;
   115	          const now = this.clock();
   116	          const form = decodeForm(input, country, now);
   117	          if (!form) return unavailable();
   118	          const draft = reconcileDraft(form.fields, this.draft(country));
   119	          this.save(country, draft);
   120	          this.current.set({
   121	            phase: 'ready',
   122	            country,
   123	            form,
   124	            validation: evaluate(form, draft, now),
   125	          });
   126	        },
   127	        error: unavailable,
   128	      });
   129	  }
   130	
   131	  private currentCountry(): Country | null {
   132	    const state = this.current();
   133	    return state.phase === 'idle' ? null : state.country;
   134	  }
   135	
   136	  draft(country: Country): QuoteDraft {
   137	    return this.drafts()[country] ?? restore(country);
   138	  }
   139	
   140	  draftRevision(country: Country) {
   141	    return this.draftRevisions()[country] ?? 0;
   142	  }
   143	
   144	  save(country: Country, draft: QuoteDraft) {
   145	    const previous = this.draft(country);
   146	    const changed =
   147	      Object.keys(previous).length !== Object.keys(draft).length ||
   148	      Object.entries(draft).some(([id, entry]) => {
   149	        const prior = previous[id];
   150	        return prior?.kind !== entry.kind || prior?.value !== entry.value;
   151	      });
   152	    if (changed) {
   153	      this.draftRevisions.update((revisions) => ({
   154	        ...revisions,
   155	        [country]: (revisions[country] ?? 0) + 1,
   156	      }));
   157	    }
   158	    this.drafts.update((drafts) => ({ ...drafts, [country]: draft }));
   159	    const state = this.current();
   160	    if (state.phase === 'ready' && state.country === country && state.validation) {
   161	      this.current.set({ ...state, validation: undefined });
   162	    }
   163	    try {
   164	      sessionStorage.setItem(storageKey(country), JSON.stringify({ version: 1, country, draft }));
   165	    } catch {
   166	      // The in-memory copy remains available for this page session.
   167	    }
   168	  }
   169	
   170	  canContinue(country: Country): boolean {
   171	    const state = this.current();
   172	    if (state.phase !== 'ready' || state.country !== country) return false;
   173	    const now = this.clock();
   174	    const validation =
   175	      civilDate(now) === state.validation?.date
   176	        ? state.validation
   177	        : evaluate(state.form, this.draft(country), now);
   178	    return validation.invalidFields.length === 0;
   179	  }
   180	}
